class Solution {
public:
    int threeSumMulti(vector<int>& arr, int target) {
        long long MOD = 1000000007;
        vector<long long> c(101, 0);
        for (int x : arr) c[x]++;
        long long ans = 0;
        for (int i = 0; i <= 100; i++) {
            for (int j = i; j <= 100; j++) {
                int k = target - i - j;
                if (k < j || k > 100) continue;
                if (i == j && j == k) {
                    ans = (ans + c[i] * (c[i] - 1) * (c[i] - 2) / 6) % MOD;
                } else if (i == j && j != k) {
                    ans = (ans + c[i] * (c[i] - 1) / 2 * c[k]) % MOD;
                } else if (i != j && j == k) {
                    ans = (ans + c[i] * c[j] * (c[j] - 1) / 2) % MOD;
                } else {
                    ans = (ans + c[i] * c[j] * c[k]) % MOD;
                }
            }
        }
        return ans;
    }
};

