var threeSumMulti = function(arr, target) {
    const MOD = 1000000007n;
    const c = new Array(101).fill(0n);
    for (const x of arr) c[x]++;
    let ans = 0n;
    for (let i = 0; i <= 100; i++) {
        for (let j = i; j <= 100; j++) {
            const k = target - i - j;
            if (k < j || k > 100) continue;
            if (i === j && j === k) {
                ans = (ans + (c[i] * (c[i] - 1n) * (c[i] - 2n)) / 6n) % MOD;
            } else if (i === j && j !== k) {
                ans = (ans + ((c[i] * (c[i] - 1n)) / 2n) * c[k]) % MOD;
            } else if (i !== j && j === k) {
                ans = (ans + c[i] * ((c[j] * (c[j] - 1n)) / 2n)) % MOD;
            } else {
                ans = (ans + c[i] * c[j] * c[k]) % MOD;
            }
        }
    }
    return Number(ans);
};
